def sha256_file(p: Path) -> tuple[str, int]:
    h = hashlib.sha256()
    with open(p, "rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest(), p.stat().st_size


def sha256_bytes(b: bytes) -> str:
    return hashlib.sha256(b).hexdigest()


